const stats = $input.first().json;
const totalQueries = stats.total_queries || 0;
const avgConfidence = stats.avg_confidence != null ? (stats.avg_confidence * 100).toFixed(1) : 'N/A';
const escalations = stats.escalations || 0;
const resolved = totalQueries - escalations;
const resolutionRate = totalQueries > 0 ? ((resolved / totalQueries) * 100).toFixed(1) : 'N/A';
const totalDocuments = stats.total_documents || 0;
const avgResponseTime = stats.avg_response_time != null ? (stats.avg_response_time / 1000).toFixed(2) + 's' : 'N/A';
const topQuestions = (stats.top_questions || []).slice(0, 5).map(function(q, i) { return (i + 1) + '. ' + q; }).join('\n');
const startDate = new Date();
startDate.setDate(startDate.getDate() - 7);
const endDate = new Date();
const formatDate = function(d) { return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); };
const message = '📈 FlowMind Weekly Analytics\n📅 ' + formatDate(startDate) + ' - ' + formatDate(endDate) + '\n\n' + '🔍 Total Queries: ' + totalQueries + '\n' + '✅ Resolved: ' + resolved + '\n' + '🚨 Escalated: ' + escalations + '\n' + '📈 Resolution Rate: ' + resolutionRate + '%\n' + '🧠 Avg Confidence: ' + avgConfidence + '%\n' + '⏱ Avg Response Time: ' + avgResponseTime + '\n' + '📄 Total Documents: ' + totalDocuments + '\n\n' + '🔥 Top Questions:\n' + (topQuestions || 'No data');
return [{ json: { message: message, totalQueries: totalQueries, escalations: escalations, avgConfidence: avgConfidence, resolutionRate: resolutionRate, period: formatDate(startDate) + ' to ' + formatDate(endDate) } }];
